// Renders the app icons into public/icons/ from one geometry: a white check mark on the
// brand blue. Dependency-free (zlib + a hand-written PNG encoder) so the committed PNGs
// can be regenerated byte for byte: `node apps/web/scripts/generate-icons.mjs`.
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { deflateSync } from 'node:zlib';

const OUT_DIR = join(dirname(fileURLToPath(import.meta.url)), '..', 'public', 'icons');

const BACKGROUND = [0x25, 0x63, 0xeb];
const FOREGROUND = [0xff, 0xff, 0xff];
// Unit coordinates. Every point lies inside the maskable safe zone (a centred circle of
// radius 0.4), so the same mark works for "any" and "maskable" icons.
const CHECK = [
  [0.3, 0.52],
  [0.44, 0.66],
  [0.71, 0.37],
];
const STROKE = 0.09;
const CORNER = 0.22;
const SUPERSAMPLE = 4;

function insideRoundedSquare(x, y, radius) {
  const cx = Math.min(Math.max(x, radius), 1 - radius);
  const cy = Math.min(Math.max(y, radius), 1 - radius);
  return (x - cx) ** 2 + (y - cy) ** 2 <= radius ** 2;
}

function distanceToSegment(px, py, [ax, ay], [bx, by]) {
  const dx = bx - ax;
  const dy = by - ay;
  const t = Math.min(Math.max(((px - ax) * dx + (py - ay) * dy) / (dx * dx + dy * dy), 0), 1);
  return Math.hypot(px - (ax + t * dx), py - (ay + t * dy));
}

function onCheck(x, y) {
  for (let i = 0; i < CHECK.length - 1; i += 1) {
    if (distanceToSegment(x, y, CHECK[i], CHECK[i + 1]) <= STROKE / 2) return true;
  }
  return false;
}

function render(size, rounded) {
  const pixels = Buffer.alloc(size * size * 4);
  const n = SUPERSAMPLE * SUPERSAMPLE;
  for (let py = 0; py < size; py += 1) {
    for (let px = 0; px < size; px += 1) {
      let bg = 0;
      let fg = 0;
      for (let sy = 0; sy < SUPERSAMPLE; sy += 1) {
        for (let sx = 0; sx < SUPERSAMPLE; sx += 1) {
          const x = (px + (sx + 0.5) / SUPERSAMPLE) / size;
          const y = (py + (sy + 0.5) / SUPERSAMPLE) / size;
          if (rounded && !insideRoundedSquare(x, y, CORNER)) continue;
          if (onCheck(x, y)) fg += 1;
          else bg += 1;
        }
      }
      const alpha = (bg + fg) / n;
      const offset = (py * size + px) * 4;
      for (let c = 0; c < 3; c += 1) {
        const mixed = alpha === 0 ? 0 : (BACKGROUND[c] * bg + FOREGROUND[c] * fg) / (bg + fg);
        pixels[offset + c] = Math.round(mixed);
      }
      pixels[offset + 3] = Math.round(alpha * 255);
    }
  }
  return pixels;
}

const CRC_TABLE = Array.from({ length: 256 }, (_, n) => {
  let c = n;
  for (let k = 0; k < 8; k += 1) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
  return c >>> 0;
});

function crc32(bytes) {
  let c = 0xffffffff;
  for (const b of bytes) c = CRC_TABLE[(c ^ b) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

function chunk(type, data) {
  const length = Buffer.alloc(4);
  length.writeUInt32BE(data.length);
  const body = Buffer.concat([Buffer.from(type, 'ascii'), data]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(body));
  return Buffer.concat([length, body, crc]);
}

function encodePng(size, pixels) {
  const header = Buffer.alloc(13);
  header.writeUInt32BE(size, 0);
  header.writeUInt32BE(size, 4);
  header[8] = 8; // bit depth
  header[9] = 6; // RGBA
  const rows = Buffer.alloc(size * (size * 4 + 1));
  for (let y = 0; y < size; y += 1) {
    pixels.copy(rows, y * (size * 4 + 1) + 1, y * size * 4, (y + 1) * size * 4);
  }
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk('IHDR', header),
    chunk('IDAT', deflateSync(rows, { level: 9 })),
    chunk('IEND', Buffer.alloc(0)),
  ]);
}

function svg() {
  const hex = (rgb) => `#${rgb.map((c) => c.toString(16).padStart(2, '0')).join('')}`;
  const points = CHECK.map(([x, y]) => `${x * 100},${y * 100}`).join(' ');
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100">` +
    `<rect width="100" height="100" rx="${CORNER * 100}" fill="${hex(BACKGROUND)}"/>` +
    `<polyline points="${points}" fill="none" stroke="${hex(FOREGROUND)}" ` +
    `stroke-width="${STROKE * 100}" stroke-linecap="round" stroke-linejoin="round"/></svg>\n`
  );
}

mkdirSync(OUT_DIR, { recursive: true });
const icons = [
  ['icon-192.png', 192, true],
  ['icon-512.png', 512, true],
  ['maskable-512.png', 512, false],
  // iOS ignores manifest icons for the Home Screen and masks this one itself.
  ['apple-touch-icon-180.png', 180, false],
];
for (const [name, size, rounded] of icons) {
  writeFileSync(join(OUT_DIR, name), encodePng(size, render(size, rounded)));
}
writeFileSync(join(OUT_DIR, 'icon.svg'), svg());
